/// 🪪️ The registered codec supplies its genuine typed input source and required receiver without a cold conversion.
pub struct NativeReceivingOriginal<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync=I>{original:ManuallyDrop<Option<OriginalInput<I,A>>>,receiver:semio_framework_value_native_storage::NativeOwnedStorage<T::Receiver>,retired_header:Option<Box<T::Receiver>>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,action:semio_framework_value_native_receiver_protocol::NativeReceivingChild,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native original receiving is not in the required funded phase")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(copy_bytes:usize)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:copy_bytes,..Default::default()}}
fn nested(mut d:RetirementDemand,copy:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(copy).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> NativeReceivingOriginal<I,T,A>{
 pub fn new(original:RetainedCloneSource<I,A>)->Self{Self{original:ManuallyDrop::new(Some(OriginalInput::Source(original))),receiver:semio_framework_value_native_storage::NativeOwnedStorage::empty(),retired_header:None,output:ManuallyDrop::new(None),retirement:Default::default(),action:Default::default(),closing:false}}
 pub fn borrow_input(&self)->Result<RetainedCloneRef<'_,I>,ValueError>{if self.closing{return Err(invalid())}self.original.as_ref().ok_or_else(invalid)?.try_borrow()}
 pub fn demands(&self,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}if let Some(d)=self.action.demand{return Ok(d)}if !self.receiver.reserved(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::reserve_demand())}if !self.receiver.initialized(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::seed_demand())}let receiver=self.receiver.get().ok_or_else(||ValueError::invariant("get target absent"))?;nested(if receiver.output_ready(){receiver.take_demand()?}else{receiver.demands(self.borrow_input()?,body,maximum_work_units)?},0)}
 pub fn advance(&mut self,control:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{semio_framework_value_native_receiver_protocol::native_receive_zero_work!(maximum_work_units);let mut work=0;let result:Result<RetainedCloneStep,OriginalReceivingPrimary>=(||{let d=self.demands(body,maximum_work_units)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.action.demand.is_none(){control.checkpoint()?;crate::owned::receiving_capacity(control,d.capacity_bytes)?;}if !self.receiver.reserved()||self.action.tag==2{self.action.tag=2;let units=self.action.work.unwrap_or_else(||self.receiver.reserve_work_demand());let turn=self.action.poll(control,d,g,units,maximum_work_units,|_,effect|self.receiver.reserve_empty(effect));work=turn.work;return turn.result}if !self.receiver.initialized()||self.action.tag==3{self.action.tag=3;let units=self.action.work.unwrap_or_else(||self.receiver.seed_work_demand());let turn=self.action.poll(control,d,g,units,maximum_work_units,|_,effect|self.receiver.initialize_seed(effect,||Ok(T::receiver())));work=turn.work;return turn.result}let receiver=self.receiver.get_mut().ok_or_else(||ValueError::invariant("get_mut target absent"))?;let child=RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g};if receiver.output_ready(){let turn=receiver.take(child);work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.output=Some(value);return Ok(RetainedCloneStep::Complete(p))}let turn=receiver.advance(self.original.as_ref().ok_or_else(invalid)?.try_borrow()?,control,body,maximum_work_units,child);work=turn.work;turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)})();RetainedWorkOutcome{result,work}}
 pub fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 semio_framework_value_native_receiver_protocol::native_owned_public_output!(T,invalid,output_ready);
 pub fn begin_close(&mut self){self.closing=true;if let Some(receiver)=self.receiver.get_mut(){receiver.begin_close()}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.receiver.reserved()||self.retired_header.is_some(){return crate::owned::native_receiver_backing_demands::<I,T,_>(&self.receiver,&self.retired_header,body)}if !self.retirement.is_empty(){return nested(self.retirement.next_owner_demands::<T>(false,&None,body)?,0)}if self.action.failure.is_some(){return nested(self.action.failure_demand(&self.retirement,body)?,0)}if self.output.is_some(){return nested(self.retirement.next_owner_demands::<T>(true,&None,body)?,0)}if let Some(original)=self.original.as_ref(){return if original.terminal_is_empty(){Ok(fixed(0))}else{nested(original.next_close_demand(body)?,0)}}Ok(Default::default())}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if let Some(receiver)=self.receiver.get(){if !receiver.terminal_is_empty(){return receiver.close_work_demand(body)}}if self.receiver.reserved()||self.retired_header.is_some(){return Ok(1)}if !self.retirement.is_empty(){return self.retirement.next_owner_work::<T>(false,&None,body)}if self.action.failure.is_some(){return self.action.failure_work(&self.retirement,body)}if self.output.is_some(){return self.retirement.next_owner_work::<T>(true,&None,body)}match self.original.as_ref(){Some(original)if !original.terminal_is_empty()=>original.close_work_demand(body),Some(_)=>Ok(1),None=>Ok(0)}}
 pub fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{if self.requires_original_control(){return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native original receiver requires its original close loan").into()),work:0}}let g=effect.grant();let mut work=0;let result:Result<RetainedCloneStep,crate::OriginalRetirementFailure>=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};if self.receiver.reserved()||self.retired_header.is_some(){let turn=if let Some(receiver)=self.receiver.get_mut().filter(|receiver|!receiver.terminal_is_empty()){receiver.close_step(&mut effect.reborrow(child,effect.maximum_work_units()).expect("retirement child exceeds original effect"))}else{crate::owned::close_native_receiver_backing::<I,T,_>(&mut self.receiver,&mut self.retired_header,effect)};work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(&mut effect.reborrow(child,effect.maximum_work_units()).expect("retirement child exceeds original effect"));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.action.failure.is_some(){let turn=self.action.close_failure(&mut self.retirement,&mut effect.reborrow(child,effect.maximum_work_units()).expect("original failure exceeds its parent effect"));work=turn.work;return turn.result}if self.output.is_some(){let turn=self.retirement.begin_granted(&mut self.output,&mut effect.reborrow(child,effect.maximum_work_units()).expect("retirement child exceeds original effect"));work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)}if let Some(original)=self.original.as_mut(){if !original.terminal_is_empty(){let turn=original.close_step(&mut effect.reborrow(child,effect.maximum_work_units()).expect("retirement child exceeds original effect"));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}work=1;self.original.take();return Ok(RetainedCloneStep::Complete(receipt(0)))}Ok(RetainedCloneStep::Complete(Default::default()))})();RetainedWorkOutcome{result,work}}
 /// 👶️ Selects an unfinished birth before any general close effect is opened.
 pub fn requires_original_birth(&self)->bool{if let Some(receiver)=self.receiver.get(){if !receiver.terminal_is_empty(){return receiver.requires_original_birth()}}if self.receiver.reserved()||self.retired_header.is_some(){return false}self.retirement.requires_original_birth()}
 /// 🧷️ Resumes the same recipient’s pending physical birth without creating another marker.
 pub fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementOutcome{if grant.maximum_items==0||grant.maximum_depth==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let child=RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant};if let Some(receiver)=self.receiver.get_mut(){if !receiver.terminal_is_empty()&&receiver.requires_original_birth(){return receiver.close_original_birth_step(original,child)}}if !self.receiver.reserved()&&self.retired_header.is_none()&&self.retirement.requires_original_birth(){return self.retirement.step_original_birth(original,child)}RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native original receiver has no birth to settle").into()),work:0}}
 /// 🪪️ Reports whether the selected original receiver needs its own close loan.
 pub fn requires_original_control(&self)->bool{if self.action.pending(){return true}if let Some(receiver)=self.receiver.get(){if !receiver.terminal_is_empty(){return receiver.requires_original_control()}}if self.receiver.reserved()||self.retired_header.is_some(){return false}self.retirement.requires_original_control()}
 /// 🧵️ Relays the exact original loan to the active receiver or retirement owner.
 pub fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{if self.action.pending(){return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original receiver birth requires settlement").into()),work:0}}if self.requires_original_birth(){return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"settle original birth before opening a close effect").into()),work:0}}let g=effect.grant();let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(error)=>return RetainedWorkOutcome{result:Err(error.into()),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};if let Some(receiver)=self.receiver.get_mut(){if !receiver.terminal_is_empty()&&receiver.requires_original_control(){return receiver.close_original_step(original,&mut effect.reborrow(child,effect.maximum_work_units()).expect("retirement child exceeds original effect"))}}if !self.receiver.reserved()&&self.retired_header.is_none()&&self.retirement.requires_original_control(){return self.retirement.step_original(original,&mut effect.reborrow(child,effect.maximum_work_units()).expect("retirement child exceeds original effect"))}self.close_step(effect)}
 pub fn terminal_is_empty(&self)->bool{self.receiver.terminal_is_empty()&&self.retired_header.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.action.terminal_is_empty()&&self.original.is_none()}
}
/// 🌱️ Inline seed starts the actual receiver close only after a funded retirement turn.
#[doc(hidden)]
pub struct NativeReceivingOriginalSeed<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync>{owner:ManuallyDrop<Option<NativeReceivingOriginal<I,T,A>>>,started:bool}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetireOwned for NativeReceivingOriginal<I,T,A>{type RetirementCursor=NativeReceivingOriginalSeed<I,T,A>;fn retirement_seed(self)->Self::RetirementCursor{NativeReceivingOriginalSeed{owner:ManuallyDrop::new(Some(self)),started:false}}fn controlled_retirement_supported()->bool{true}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetirementCursor for NativeReceivingOriginalSeed<I,T,A>{
 fn requires_original_birth(&self)->bool{self.started&&self.owner.as_ref().is_some_and(NativeReceivingOriginal::requires_original_birth)}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->RetirementStep{let Some(owner)=self.owner.as_mut()else{return RetirementStep::Complete(0)};let turn=owner.close_original_birth_step(original,grant);match turn.result{Ok(step)=>RetirementStep::Progress(step.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}
 fn requires_original_control(&self)->bool{self.started&&self.owner.as_ref().is_some_and(NativeReceivingOriginal::requires_original_control)}
 fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{let Some(owner)=self.owner.as_mut()else{return RetirementStep::Complete(0)};let turn=owner.close_original_step(original,effect);match turn.result{Ok(step)=>RetirementStep::Progress(step.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}
 fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{match self.owner.as_ref(){None=>Ok(Default::default()),Some(owner)if self.started=>owner.close_demands(body),Some(_)=>Ok(fixed(0))}}
 fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{match self.owner.as_ref(){None=>Ok(0),Some(owner)if self.started=>owner.close_work_demand(body),Some(_)=>Ok(1)}}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{let g=effect.grant();if self.terminal_is_empty(){return RetirementStep::Complete(0)}if !self.started{if effect.maximum_work_units()==0||!retained_clone_grant_admits(g,fixed(0)){return RetirementStep::BudgetExhausted}self.owner.as_mut().expect("retained original receiver").begin_close();self.started=true;return RetirementStep::Progress(receipt(0),1)}let turn=self.owner.as_mut().expect("retained original receiver").close_step(effect);match turn.result{Ok(step)=>RetirementStep::Progress(step.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}
 fn terminal_is_empty(&self)->bool{self.started&&self.owner.as_ref().is_none_or(NativeReceivingOriginal::terminal_is_empty)}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> Drop for NativeReceivingOriginalSeed<I,T,A>{fn drop(&mut self){if !std::thread::panicking(){assert!(self.terminal_is_empty(),"original receiver seed requires funded closure");unsafe{ManuallyDrop::drop(&mut self.owner)}}}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetirementCursor for NativeReceivingOriginal<I,T,A>{fn requires_original_birth(&self)->bool{Self::requires_original_birth(self)}fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->RetirementStep{let turn=Self::close_original_birth_step(self,original,grant);match turn.result{Ok(step)=>RetirementStep::Progress(step.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}fn requires_original_control(&self)->bool{Self::requires_original_control(self)}fn close_original_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{let turn=Self::close_original_step(self,original,effect);match turn.result{Ok(step)=>RetirementStep::Progress(step.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close_demands(body)}fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{self.close_work_demand(body)}fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->RetirementStep{let g=effect.grant();let turn=Self::close_step(self,&mut effect.reborrow(g,effect.maximum_work_units()).expect("retirement child exceeds original effect"));match turn.result{Ok(s)=>RetirementStep::Progress(s.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}fn terminal_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> Drop for NativeReceivingOriginal<I,T,A>{fn drop(&mut self){assert!(self.terminal_is_empty(),"native receiving keeps original custody until funded closure");}}
